import * as T from './vendor/three.module.min.js';
export function createScene(canvas,onStats){
const renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0xffffff);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1;
const scene=new T.Scene(),camera=new T.PerspectiveCamera(40,1,.05,250);scene.add(new T.HemisphereLight(0xffffff,0x85919d,1.5));const light=new T.DirectionalLight(0xffffff,2);light.position.set(3,6,4);scene.add(light);
const drone=new T.Group();scene.add(drone);let groups={},rotors=[],modelScale=1;
const mat=(color,metalness=.2)=>new T.MeshStandardMaterial({color,metalness,roughness:.42});const graphite=mat(0x2e3642),silver=mat(0x8b949e,.35),sky=mat(0x648394),board=mat(0x596680),white=mat(0xffffff),dark=mat(0x1d1d1f);
function box(parent,x,y,z,w,h,d,m){const o=new T.Mesh(new T.BoxGeometry(w,h,d),m);o.position.set(x,y,z);parent.add(o);return o;}
function cylinder(parent,x,y,z,r,h,m){const o=new T.Mesh(new T.CylinderGeometry(r,r,h,32),m);o.position.set(x,y,z);parent.add(o);return o;}
function build(){for(const c of [...drone.children]){drone.remove(c);c.traverse(o=>o.geometry?.dispose());}groups={};rotors=[];for(const id of ['frame','motor','esc','fc','rx','battery','prop']){groups[id]=new T.Group();drone.add(groups[id]);}
box(groups.frame,0,0,0,.74,.10,1.05,graphite);box(groups.frame,0,.075,0,.67,.035,.85,silver);
for(let i=0;i<4;i++){const x=i%2===0?-.95:.95,z=i<2?-.95:.95;let arm=box(groups.frame,x/2,0,z/2,1.36,.085,.14,graphite);arm.rotation.y=-Math.atan2(z,x);cylinder(groups.frame,x,-.06,z,.19,.035,silver);box(groups.frame,x*.75,-.20,z*.75,.06,.32,.06,silver);cylinder(groups.motor,x,.075,z,.15,.18,graphite);cylinder(groups.motor,x,.17,z,.13,.055,silver);cylinder(groups.motor,x,.21,z,.035,.045,dark);const r=new T.Group();r.position.set(x,.25,z);groups.prop.add(r);rotors.push(r);const blade=new T.Mesh(new T.CapsuleGeometry(.052,.9,4,10),i<2?sky:graphite);blade.rotation.z=Math.PI/2;blade.scale.y=1.5;blade.scale.z=.16;r.add(blade);cylinder(r,0,0,0,.065,.055,silver);r.rotation.y=i*Math.PI/4;}
box(groups.esc,0,.14,0,.43,.05,.43,board);for(let i=0;i<4;i++)box(groups.esc,(i%2?1:-1)*.13,.18,(i<2?-1:1)*.12,.12,.035,.10,dark);
box(groups.fc,0,.28,0,.40,.035,.40,sky);box(groups.fc,0,.31,0,.13,.035,.13,dark);for(let i=0;i<4;i++)cylinder(groups.fc,(i%2?1:-1)*.16,.22,(i<2?-1:1)*.16,.02,.15,silver);
box(groups.battery,0,.46,.07,.39,.23,.72,graphite);box(groups.battery,0,.465,.08,.42,.24,.13,sky);box(groups.battery,0,.585,-.14,.22,.012,.11,silver);
box(groups.rx,0,.16,.42,.22,.055,.16,board);const antenna=cylinder(groups.rx,.05,.30,.5,.008,.35,dark);antenna.rotation.z=-.5;
// Front marker indicates the aircraft's forward (-Z) direction.
box(groups.frame,0,.11,-.50,.19,.018,.06,sky);
}
build();
// Unlit edges preserve the silhouette of small parts against the light workbench.
for(const group of Object.values(groups)){
  const meshes=[];group.traverse(o=>{if(o.isMesh)meshes.push(o);});
  for(const mesh of meshes){const edge=new T.LineSegments(new T.EdgesGeometry(mesh.geometry,30),new T.LineBasicMaterial({color:0x26323d}));mesh.add(edge);}
}
const wireGroup=new T.Group();drone.add(wireGroup);
const wireEnds=[[[.15,.58,.07],[.22,.16,0]],[[-.15,.58,.07],[-.22,.16,0]],[[.12,.16,0],[.12,.28,0]],[[-.12,.16,0],[-.12,.28,0]],...Array.from({length:4},(_,i)=>[[(i-1.5)*.09,.29,-.18],[(i-1.5)*.09,.16,-.18]]),[[.14,.28,.15],[.08,.16,.42]],[[-.14,.28,.15],[-.08,.16,.42]],[[0,.16,.42],[0,.28,.18]],...Array.from({length:4},(_,i)=>[[i%2?.2:-.2,.16,i<2?-.2:.2],[i%2?.95:-.95,.12,i<2?-.95:.95]])];
const wireLines=wireEnds.map((ends,i)=>{const a=new T.Vector3(...ends[0]),b=new T.Vector3(...ends[1]);const middle=a.clone().lerp(b,.5);middle.y+=.15;const curve=new T.CatmullRomCurve3([a,middle,b]);const line=new T.Mesh(new T.TubeGeometry(curve,16,.009,5,false),mat(i===0?0xb64400:0x596680));line.visible=false;wireGroup.add(line);return line;});
const floor=new T.Group();scene.add(floor);const ground=new T.Mesh(new T.PlaneGeometry(180,180),new T.MeshBasicMaterial({color:0xf5f5f7,toneMapped:false}));ground.rotation.x=-Math.PI/2;ground.position.y=-.36;floor.add(ground);const grid=new T.GridHelper(160,80,0x303841,0x757e88);grid.position.y=-.34;grid.material.toneMapped=false;grid.material.fog=false;floor.add(grid);const majorGrid=new T.GridHelper(160,16,0x202830,0x46515c);majorGrid.position.y=-.33;majorGrid.material.toneMapped=false;majorGrid.material.fog=false;floor.add(majorGrid);
const pad=new T.Mesh(new T.RingGeometry(1.4,1.48,64),mat(0x707070,0));pad.rotation.x=-Math.PI/2;pad.position.y=-.34;floor.add(pad);const inner=new T.Mesh(new T.RingGeometry(.20,.22,40),mat(0x707070,0));inner.rotation.x=-Math.PI/2;inner.position.y=-.33;floor.add(inner);floor.visible=false;
let mode='build',yaw=.6,pitch=.72,distance=6.9,selected='',mounted=new Set(),partSize=5;const pointers=new Map();let pinch=0;
canvas.addEventListener('pointerdown',e=>{if(mode==='fly')return;canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const p=[...pointers.values()];pinch=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);}});
canvas.addEventListener('pointermove',e=>{const old=pointers.get(e.pointerId);if(!old)return;const dx=e.clientX-old.x,dy=e.clientY-old.y;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const p=[...pointers.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);distance=T.MathUtils.clamp(distance*pinch/Math.max(1,d),3.6,12);pinch=d;}else{yaw-=dx*.008;pitch=T.MathUtils.clamp(pitch+dy*.006,.12,1.5);}});
for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,e=>pointers.delete(e.pointerId));canvas.addEventListener('wheel',e=>{if(mode==='fly')return;e.preventDefault();distance=T.MathUtils.clamp(distance+e.deltaY*.007,3.6,12);},{passive:false});
const flight={running:false,land:false,position:new T.Vector3(),velocity:new T.Vector3(),yaw:0,roll:0,pitch:0,energy:1,elapsed:0,status:'離陸できます'};const input={lx:0,ly:0,rx:0,ry:0};let metrics=null,last=performance.now(),statsAt=0;
function resetFlight(){flight.position.set(0,0,0);flight.velocity.set(0,0,0);flight.yaw=0;flight.roll=0;flight.pitch=0;flight.energy=metrics?.energy||1;flight.elapsed=0;flight.running=false;flight.land=false;flight.status='離陸できます';Object.keys(input).forEach(k=>input[k]=0);}
const target=new T.Vector3(),up=new T.Vector3(),euler=new T.Euler(0,0,0,'YXZ');
function animate(now){const dt=Math.min((now-last)/1000,1/30);last=now;if(mode==='fly'){
if(flight.running&&metrics){flight.elapsed+=dt;const f=flight;f.yaw-=input.lx*Math.PI/2*dt;const k=1-Math.exp(-dt/.18);f.roll+=(-input.rx*.42-f.roll)*k;f.pitch+=(-input.ry*.42-f.pitch)*k;const vz=f.land?-1:input.ly*2;const az=T.MathUtils.clamp(2.5*(vz-f.velocity.y),-4,4);let thrust=T.MathUtils.clamp(metrics.mass*(9.81+az)/Math.max(.4,Math.cos(f.roll)*Math.cos(f.pitch)),0,metrics.thrust);if(f.energy<=0)thrust=0;euler.set(f.pitch,f.yaw,f.roll,'YXZ');up.set(0,1,0).applyEuler(euler);f.velocity.x+=(up.x*thrust/metrics.mass-.7*f.velocity.x)*dt;f.velocity.z+=(up.z*thrust/metrics.mass-.7*f.velocity.z)*dt;f.velocity.y+=(up.y*thrust/metrics.mass-9.81)*dt;f.position.addScaledVector(f.velocity,dt);f.energy=Math.max(0,f.energy-metrics.power(thrust/metrics.thrust)*dt/3600);
if(f.position.y<=0){const hard=f.velocity.y< -2.5;f.position.y=0;f.velocity.y=0;if(f.land||f.energy<=0||hard){f.running=false;f.land=false;f.velocity.set(0,0,0);f.status=hard?'強い着地。リセットで再開できます。':f.energy<=0?'使用可能エネルギーがなくなりました。':'着陸しました';}}
if(f.position.y>35){f.position.y=35;f.velocity.y=Math.min(0,f.velocity.y);f.status='高度上限 35 m';}else if(f.running)f.status=f.land?'着陸中':'高度アシスト ON';if(Math.hypot(f.position.x,f.position.z)>65){f.position.x=T.MathUtils.clamp(f.position.x,-45,45);f.position.z=T.MathUtils.clamp(f.position.z,-45,45);f.velocity.x=0;f.velocity.z=0;f.status='飛行エリアの端です';}}
drone.position.copy(flight.position);drone.rotation.set(flight.pitch,flight.yaw,flight.roll,'YXZ');const cameraOffset=new T.Vector3(0,3.4,6.5).applyAxisAngle(new T.Vector3(0,1,0),flight.yaw);target.copy(flight.position).add(cameraOffset);camera.position.lerp(target,1-Math.exp(-dt*5));camera.lookAt(flight.position.clone().add(new T.Vector3(0,.4,0)));if(flight.running)rotors.forEach((r,i)=>r.rotation.y+=dt*80*(i===0||i===3?1:-1));if(now-statsAt>100){onStats({...flight,speed:Math.hypot(flight.velocity.x,flight.velocity.y,flight.velocity.z),altitude:flight.position.y,percent:metrics?100*flight.energy/metrics.energy:100});statsAt=now;}
}else{drone.position.set(0,-.13,0);drone.rotation.set(0,0,0);camera.position.set(Math.sin(yaw)*Math.cos(pitch)*distance,Math.sin(pitch)*distance,Math.cos(yaw)*Math.cos(pitch)*distance);camera.lookAt(0,.15,0);}
renderer.render(scene,camera);requestAnimationFrame(animate);}
requestAnimationFrame(animate);const resize=new ResizeObserver(()=>{const r=canvas.parentElement.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();});resize.observe(canvas.parentElement);
return {setConnections(ids){wireLines.forEach((line,i)=>line.visible=ids.has(i));},setConfiguration(c){modelScale=[.83,1,1.15][c.frame];groups.frame.scale.set(modelScale,1,modelScale);groups.motor.scale.set(modelScale,1,modelScale);groups.prop.scale.set(modelScale,1,modelScale);groups.battery.scale.set(1,[.8,1,1.22][c.battery],1);},setMode(m){mode=m;floor.visible=m==='fly';wireGroup.visible=m==='wiring';scene.fog=m==='fly'?new T.Fog(0xf5f5f7,35,100):null;renderer.setClearColor(m==='fly'?0xf5f5f7:0xffffff);flight.running=false;Object.keys(input).forEach(k=>input[k]=0);if(m==='fly')camera.position.set(0,3.4,6.5);this.update(mounted,selected,partSize);},update(set,sel,size){mounted=new Set(set);selected=sel;partSize=size;for(const [id,g]of Object.entries(groups)){g.visible=mode!=='build'||mounted.has(id)||id===sel;g.traverse(o=>{if(!o.isMesh)return;if(!o.userData.base)o.userData.base=o.material;if(!o.userData.ghost)o.userData.ghost=new T.MeshBasicMaterial({color:0x758493});o.material=mode==='build'&&!mounted.has(id)?o.userData.ghost:o.userData.base;});}rotors.forEach(r=>r.scale.set(size/5,1,size/5));},setMetrics(m){metrics=m;resetFlight();},zoom(n){distance=T.MathUtils.clamp(distance+n,3.6,12);},resetView(){yaw=.6;pitch=.72;distance=6.9;},input,flight,start(){if(!metrics||metrics.errors.length)return false;if(flight.position.y===0){flight.position.y=.1;flight.velocity.y=1.7;}flight.running=true;flight.land=false;flight.status='高度アシスト ON';return true;},pause(){flight.running=false;Object.keys(input).forEach(k=>input[k]=0);flight.status='一時停止';},land(){if(flight.position.y>0){flight.running=true;flight.land=true;}},reset:resetFlight};
}
